CREATE TABLE `plants` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `family` varchar(50) DEFAULT NULL,
  `type_of_life` enum('Квітуча','Декоративна','Сезонна','Багаторічна','Однорічна') DEFAULT NULL,
  `height` text,
  `flower_color` varchar(100) DEFAULT NULL,
  `flowering_period` varchar(50) DEFAULT NULL,
  `conditions_of_care` text,
  `growth_regions` varchar(200) DEFAULT NULL,
  `soil` varchar(100) DEFAULT NULL,
  `temperature` varchar(50) DEFAULT NULL,
  `recommended_humidity` varchar(50) DEFAULT NULL,
  `image` text,
  `description` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=118 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
